    await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, target.id, { title: "Target first" }));
    await commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: b.id, body: "a comment", parentId: null, mentionedUserIds: [] });

    const events: Record<string, unknown[]> = {};
    for (const type of ["issue.moved", "issue.created", "issue.updated", "issue.archived", "issue.status_changed", "issue.assigned"] as const) {
      events[type] = [];
      offs.push(subscribe(type, (p) => { events[type]!.push(p); }));
    }

    const input = moveIssueToProjectSchema.parse({ orgId: tenant.org.id, issueId: b.id, toProjectId: target.id });
    const moved = await issueService.moveIssueToProject(tenant.actors.member, input);

    expect(moved.projectId).toBe(target.id);
    expect(moved.number).toBe(2);
    expect(moved).toMatchObject({ title: b.title, priority: "high", estimate: 3, assigneeId: tenant.userIds.admin, status: b.status, labelIds: [label.id] });
    expect(await issueRepo.findIssueById(tenant.org.id, b.id)).toEqual(moved);

    expect(events["issue.moved"]).toEqual([
      expect.objectContaining({ orgId: tenant.org.id, actorId: tenant.userIds.member, issueId: b.id, fromProjectId: tenant.project.id, toProjectId: target.id, fromNumber: b.number, toNumber: 2 }),
    ]);
    for (const t of ["issue.created", "issue.updated", "issue.archived", "issue.status_changed", "issue.assigned"]) expect(events[t]).toHaveLength(0);

    const detail = await issueService.getIssue(tenant.actors.member, tenant.org.id, b.id);
    expect(detail.commentCount).toBe(1);

    // Old number retired.
    const c = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Charlie" }));
    expect(c.number).toBe(b.number + 1);

    // Moved away and back.
    const back = await issueService.moveIssueToProject(tenant.actors.member, { orgId: tenant.org.id, issueId: b.id, toProjectId: tenant.project.id });
    expect(back.number).toBe(c.number + 1);
    const t2 = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, target.id, { title: "Target next" }));
    expect(t2.number).toBe(3);

    // Audit.
    const filter = activityFilterSchema.parse({ orgId: tenant.org.id, action: ["issue.moved"], projectId: target.id });
    const page = await activityService.listActivity(tenant.actors.member, filter);
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "issue.moved", subjectKind: "issue", subjectId: b.id, projectId: target.id, actorId: tenant.userIds.member,
      metadata: { fromProjectId: tenant.project.id, toProjectId: target.id, fromNumber: b.number, toNumber: 2 },
    });
    const created = await activityService.listActivity(tenant.actors.member, activityFilterSchema.parse({ orgId: tenant.org.id, action: ["issue.created"], projectId: tenant.project.id }));
    expect(created.items.map((e) => e.subjectId)).toContain(b.id);

    // Search follows the issue.
    const inSource = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "quokka", kinds: ["issue"], projectId: tenant.project.id, limit: 25, cursor: null });
    expect(inSource.items.map((h) => h.id)).toEqual([b.id]);
    await issueService.moveIssueToProject(tenant.actors.member, { orgId: tenant.org.id, issueId: b.id, toProjectId: target.id });
    const inTarget = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "quokka", kinds: ["issue"], projectId: target.id, limit: 25, cursor: null });
    expect(inTarget.items.map((h) => h.id)).toEqual([b.id]);
    const notInSource = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "quokka", kinds: ["issue"], projectId: tenant.project.id, limit: 25, cursor: null });
    expect(notInSource.items).toHaveLength(0);

    // Boards.
    const srcBoard = await issueService.getBoard(tenant.actors.member, tenant.org.id, tenant.project.id);
    const tgtBoard = await issueService.getBoard(tenant.actors.member, tenant.org.id, target.id);
    expect(srcBoard.flatMap((col) => col.issues.map((i) => i.id))).not.toContain(b.id);
    expect(tgtBoard.flatMap((col) => col.issues.map((i) => i.id))).toContain(b.id);
    void a;
  });

  it("same project is a no-op", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Stay put" }));
    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => { seen.push(p); });
    const result = await issueService.moveIssueToProject(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, toProjectId: tenant.project.id });
    off();
    expect(result).toEqual(issue);
    expect(seen).toHaveLength(0);
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toEqual(issue);
  });

  it("checks both permissions and changes nothing on refusal", async () => {
    const target = await newProject("PRM");
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Viewer owns", assigneeId: tenant.userIds.viewer }));
    const err = await issueService.moveIssueToProject(tenant.actors.viewer, { orgId: tenant.org.id, issueId: issue.id, toProjectId: target.id }).catch((e: unknown) => e);
    expect(err).toBeInstanceOf(PermissionDeniedError);
    expect((err as PermissionDeniedError).action).toBe("issue:create");
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toEqual(issue);
    const other = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Not viewer's" }));
    const err2 = await issueService.moveIssueToProject(tenant.actors.viewer, { orgId: tenant.org.id, issueId: other.id, toProjectId: target.id }).catch((e: unknown) => e);
    expect((err2 as PermissionDeniedError).action).toBe("issue:update");
  });

  it("applies the target quota", async () => {
    const free = await createTenant("movequota", "free");
    const target = await newProject("QTA", free);
    for (let n = 1; n <= 100; n += 1) {
      await issueRepo.insertIssue(issueInput(free.org.id, target.id, { title: `Seed ${n}` }), free.userIds.member, n);
    }
    const issue = await issueService.createIssue(free.actors.member, issueInput(free.org.id, free.project.id, { title: "Quota mover" }));
    await expect(issueService.moveIssueToProject(free.actors.member, { orgId: free.org.id, issueId: issue.id, toProjectId: target.id })).rejects.toThrow(/allows no more issues/);
    expect(await issueRepo.findIssueById(free.org.id, issue.id)).toEqual(issue);
    expect(await issueRepo.nextIssueNumber(free.org.id, target.id)).toBe(101);
  });
});
